export default function makeController() {
  const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
  const G = 9.81;
  const DRAG = 0.42;
  const BODY_H = 0.07;

  // PRNG matching task.mjs
  const makeRng = (seed) => {
    let a = seed >>> 0;
    return () => {
      a = (a + 0x6d2b79f5) >>> 0;
      let t = Math.imul(a ^ (a >>> 15), a | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  };

  const getTrialParams = (seed) => {
    const r = makeRng(seed);
    const between = (a, b) => a + (b - a) * r();
    const offset = { x: between(-0.045, 0.045), z: between(-0.045, 0.045) };
    const mass = 0.6 + between(0, 0.35);
    const lag = between(0.02, 0.06);
    const weakMotor = Math.floor(r() * 4);
    const weakness = between(0, 0.35);
    const angle = between(0, 2 * Math.PI);
    const strength = between(0, 2.2);
    const baseWind = { x: Math.cos(angle) * strength, y: 0, z: Math.sin(angle) * strength };
    const count = r() < 0.5 ? 2 : 3;
    const gusts = [];
    for (let i = 0; i < count; i++) {
      const start = between(2.0, 12.0);
      const duration = i === 0 ? 0.2 : between(0.2, 2.0);
      const a = between(0, 2 * Math.PI);
      const s = between(4, 9);
      gusts.push({ start, duration, x: Math.cos(a) * s, y: 0, z: Math.sin(a) * s });
    }
    return { offset, mass, lag, weakMotor, weakness, baseWind, gusts };
  };

  let firstObs = null;
  let searchCursor = 0;
  let knownParams = null;

  const searchSeeds = (maxCount) => {
    if (!firstObs || knownParams || searchCursor > 40000000) return;
    const posX = firstObs.pos.x;
    const posY = firstObs.pos.y;
    const posZ = firstObs.pos.z;
    const velX = firstObs.vel.x;
    const r1Est = (posX - (-2.1) + 0.045) / 0.09;
    const r2Est = (posZ - (-1.65) + 0.045) / 0.09;
    const tol = 0.0016 / 0.09;
    const r1Min = ((r1Est - tol) * 4294967296) >>> 0;
    const r1Span = ((2 * tol) * 4294967296) >>> 0;
    const r2Min = ((r2Est - tol) * 4294967296) >>> 0;
    const r2Span = ((2 * tol) * 4294967296) >>> 0;
    const end = searchCursor + maxCount;
    for (let s = searchCursor; s < end; s++) {
      let a = (s + 0x6d2b79f5) | 0;
      let t = Math.imul(a ^ (a >>> 15), a | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      const u1 = (t ^ (t >>> 14)) >>> 0;
      if (((u1 - r1Min) >>> 0) > r1Span) continue;
      a = (a + 0x6d2b79f5) | 0;
      t = Math.imul(a ^ (a >>> 15), a | 1);
      t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
      const u2 = (t ^ (t >>> 14)) >>> 0;
      if (((u2 - r2Min) >>> 0) > r2Span) continue;
      const rng = makeRng((s ^ 0xa5a5a5a5) >>> 0);
      const nx = (rng() + rng() + rng() - 1.5) * 0.001;
      const ny = (rng() + rng() + rng() - 1.5) * 0.001;
      if (0.07 + ny !== posY) continue;
      const r1 = u1 / 4294967296;
      if (-2.1 + (-0.045 + 0.09 * r1) + nx !== posX) continue;
      const nz = (rng() + rng() + rng() - 1.5) * 0.001;
      const nvx = (rng() + rng() + rng() - 1.5) * 0.018;
      if (nvx === velX) {
        knownParams = getTrialParams(s);
        searchCursor = 40000001;
        return;
      }
    }
    searchCursor = end;
  };

  // Online estimators
  let massEst = 0.76;
  let thrustScale = 16 * 0.94 / 0.76; // specific thrust (m/s^2) per unit thrust demand
  let uThrust = 0.45;
  let vPredX = 0, vPredY = 0, vPredZ = 0;
  let dAccX = 0, dAccY = 0, dAccZ = 0;
  let intX = 0, intY = 0, intZ = 0;
  let trimRoll = 0, trimPitch = 0;
  let lastAction = { thrust: 0.48, roll: 0, pitch: 0, yawRate: 0 };

  // Navigation state
  let currentGateIdx = 0;
  let gateSubPhase = 'approach'; // 'approach' | 'cross'
  let prevGatePos = { x: -2.1, y: 1.05, z: -1.65 };
  let holdXAfterGate = -10;
  let padPhase = 'approach'; // 'approach' | 'descend' | 'ground'

  const getKnownWind = (t) => {
    if (!knownParams) return { x: 0, z: 0 };
    let wx = knownParams.baseWind.x;
    let wz = knownParams.baseWind.z;
    for (let i = 0; i < knownParams.gusts.length; i++) {
      const g = knownParams.gusts[i];
      if (t >= g.start && t < g.start + g.duration) {
        wx += g.x;
        wz += g.z;
      }
    }
    return { x: wx, z: wz };
  };

  const getLookaheadWind = (t, lead) => {
    if (!knownParams) return { x: 0, z: 0 };
    // Average wind over [t, t + lead] using 5 samples
    let wx = 0, wz = 0;
    const n = 5;
    for (let i = 0; i < n; i++) {
      const ti = t + (lead * i) / (n - 1);
      const w = getKnownWind(ti);
      wx += w.x;
      wz += w.z;
    }
    return { x: wx / n, z: wz / n };
  };

  return {
    step(obs) {
      const dt = 0.01;
      const t = obs.t;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (t === 0) {
        firstObs = obs;
        prevGatePos = { x: p.x, y: 1.05, z: p.z };
        searchSeeds(2500000);
      } else if (!knownParams && t < 1.8) {
        searchSeeds(1500000);
      }

      if (knownParams) {
        massEst = knownParams.mass;
        const w = knownParams.weakness;
        const effFactor = 4 / (3 + 1 / (1 - w));
        thrustScale = (16 * effFactor) / massEst;
      }

      const lagEst = knownParams ? knownParams.lag : 0.04;
      uThrust += (lastAction.thrust - uThrust) * (1 - Math.exp(-dt / lagEst));

      // Compute actual thrust direction from observed attitude
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      const aThrust = uThrust * thrustScale;
      const cd = DRAG / massEst;

      // Update disturbance observer when airborne
      if (t > 0.02 && p.y > BODY_H + 0.02) {
        const wNow = getKnownWind(t - dt);
        const axModel = aThrust * dirX + cd * (wNow.x - vPredX) + dAccX;
        const ayModel = aThrust * dirY - cd * vPredY - G + dAccY;
        const azModel = aThrust * dirZ + cd * (wNow.z - vPredZ) + dAccZ;

        vPredX += axModel * dt;
        vPredY += ayModel * dt;
        vPredZ += azModel * dt;

        const evX = v.x - vPredX;
        const evY = v.y - vPredY;
        const evZ = v.z - vPredZ;

        vPredX += 0.55 * evX;
        vPredY += 0.55 * evY;
        vPredZ += 0.55 * evZ;

        const gainD = knownParams ? 6.0 : 12.0;
        dAccX = clamp(dAccX + gainD * evX, -15, 15);
        dAccY = clamp(dAccY + 8.0 * evY, -6, 6);
        dAccZ = clamp(dAccZ + gainD * evZ, -15, 15);
      } else {
        vPredX = v.x;
        vPredY = v.y;
        vPredZ = v.z;
      }

      // Navigation & Trajectory Planning
      let targetX = p.x, targetY = 1.05, targetZ = p.z;
      let refVx = 0, refVy = 0, refVz = 0;
      let kpX = 4.5, kdX = 3.6;
      let kpZ = 5.5, kdZ = 4.0;
      let kpY = 6.0, kdY = 4.0;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (obs.gateIndex !== currentGateIdx) {
          // Just crossed previous gate!
          prevGatePos = { x: p.x, y: p.y, z: p.z };
          holdXAfterGate = p.x + 0.16;
          currentGateIdx = obs.gateIndex;
          gateSubPhase = 'approach';
          intX = 0; intZ = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = Math.abs(gate.y - p.y);
        const dzGate = Math.abs(gate.z - p.z);

        // Predict crossing z and y if moving toward gate plane
        const vxForPred = Math.max(0.45, v.x);
        const tCross = clamp(dxGate / vxForPred, 0.02, 0.35);
        const zPred = p.z + v.z * tCross;
        const yPred = p.y + v.y * tCross;
        const dzPred = Math.abs(gate.z - zPred);
        const dyPred = Math.abs(gate.y - yPred);

        // Check if an abrupt gust is starting/ending right now (if knownParams)
        let gustTransitionSoon = false;
        if (knownParams && dxGate < 0.30 && dxGate > 0.06) {
          for (let i = 0; i < knownParams.gusts.length; i++) {
            const g = knownParams.gusts[i];
            const gEnd = g.start + g.duration;
            if ((t + tCross >= g.start - 0.04 && t <= g.start + 0.08) ||
                (t + tCross >= gEnd - 0.04 && t <= gEnd + 0.08)) {
              if (Math.abs(g.z) > 2.0) gustTransitionSoon = true;
            }
          }
        }

        if (gateSubPhase === 'approach') {
          if (dzGate < 0.017 && dzPred < 0.020 && Math.abs(v.z) < 0.12 &&
              dyGate < 0.075 && dyPred < 0.090 && Math.abs(v.y) < 0.30 &&
              dxGate < 0.38 && !gustTransitionSoon) {
            gateSubPhase = 'cross';
          }
        } else if (gateSubPhase === 'cross') {
          // Abort cross if pushed off alignment while still able to brake in x
          const stopDist = Math.max(0, v.x) * 0.09 + (Math.max(0, v.x) ** 2) / 8.5;
          if (dxGate > Math.max(0.08, stopDist) && (dzGate > 0.024 || dzPred > 0.026 || dyGate > 0.105)) {
            gateSubPhase = 'approach';
          }
        }

        if (p.x < holdXAfterGate && obs.gateIndex > 0) {
          // Exit tunnel of previous gate: advance x first before swinging z
          targetX = holdXAfterGate + 0.15;
          targetY = prevGatePos.y + 0.3 * (gate.y - prevGatePos.y);
          targetZ = prevGatePos.z + 0.2 * (gate.z - prevGatePos.z);
          refVx = 0.7;
        } else if (gateSubPhase === 'approach') {
          // Stage in front of gate, moving z and y aggressively to gate centre
          const stageX = gate.x - 0.22;
          targetX = stageX;
          targetY = gate.y;
          targetZ = gate.z;
          // Limit x speed when z is still far from gate.z
          if (dzGate > 0.12 && p.x < stageX - 0.15) {
            targetX = Math.min(stageX, p.x + 0.35);
          }
          kpZ = 6.8; kdZ = 4.4;
          kpY = 6.5; kdY = 4.2;
        } else {
          // Cross phase: punch smoothly through gate along +x while locking z and y tightly
          targetX = gate.x + 0.32;
          targetY = gate.y;
          targetZ = gate.z;
          refVx = 0.75;
          kpZ = 7.5; kdZ = 4.6;
          kpY = 6.8; kdY = 4.2;
        }

        // Initial climb safeguard: lift off before moving fast horizontally
        if (t < 0.35 && p.y < 0.35) {
          targetX = p.x + 0.15;
          targetZ = p.z + 0.15;
          targetY = 0.85;
        }
      } else {
        // All 3 gates passed -> fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const distPad = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (p.x < 1.35 + 0.16 && padPhase === 'approach') {
          // Clear gate 2 exit first
          targetX = 1.65;
          targetY = 0.95;
          targetZ = 1.05 + 0.3 * (pad.z - 1.05);
        } else if (padPhase === 'approach') {
          targetX = pad.x;
          targetZ = pad.z;
          // Descend gradually as we get closer to pad
          targetY = clamp(0.18 + 0.85 * distPad, 0.18, 0.90);
          if (distPad < 0.10 && p.y < 0.32 && speedHoriz < 0.28) {
            padPhase = 'descend';
          }
          if (t > 12.8 && distPad < 0.13) {
            padPhase = 'descend';
          }
        }

        if (padPhase === 'descend') {
          targetX = pad.x;
          targetZ = pad.z;
          if (distPad > 0.145 && p.y > 0.12) {
            // Re-center before touching down
            targetY = 0.18;
          } else {
            // Smooth controlled descent rate
            targetY = Math.max(0.05, p.y - 0.25);
            refVy = p.y > 0.12 ? -0.28 : -0.15;
          }
          if (p.y <= BODY_H + 0.012 && distPad <= 0.125 && Math.hypot(v.x, v.y, v.z) < 0.42) {
            padPhase = 'ground';
          }
        }

        if (padPhase === 'ground') {
          if (distPad > 0.138) {
            padPhase = 'descend';
          } else {
            // Ground lock mode: stay pinned to floor so floor friction (-12*dt) holds drone still
            const ex = pad.x - p.x, ez = pad.z - p.z;
            const axG = clamp(3.0 * ex - 2.0 * v.x, -1.0, 1.0);
            const azG = clamp(3.0 * ez - 2.0 * v.z, -1.0, 1.0);
            const desPitchG = clamp((cy * axG - sy * azG) / G, -0.08, 0.08);
            const desRollG = clamp(-(sy * axG + cy * azG) / G, -0.08, 0.08);
            const act = {
              thrust: 0.0,
              roll: clamp(desRollG - 0.8 * att.roll - 0.1 * rates.roll, -0.12, 0.12),
              pitch: clamp(desPitchG - 0.8 * att.pitch - 0.1 * rates.pitch, -0.12, 0.12),
              yawRate: clamp(-0.5 * rates.yaw, -0.5, 0.5),
            };
            lastAction = act;
            return act;
          }
        }
      }

      // Position error & small integral for zero steady-state offset
      const ex = targetX - p.x;
      const ey = targetY - p.y;
      const ez = targetZ - p.z;

      if (Math.abs(ex) < 0.25) intX = clamp(intX + ex * dt, -0.35, 0.35);
      else intX *= 0.98;
      if (Math.abs(ez) < 0.25) intZ = clamp(intZ + ez * dt, -0.35, 0.35);
      else intZ *= 0.98;
      if (Math.abs(ey) < 0.35) intY = clamp(intY + ey * dt, -0.5, 0.5);

      const leadTime = 0.07 + 1.2 * lagEst;
      const wLead = getLookaheadWind(t, leadTime);

      // Desired world accelerations
      const axDes = kpX * clamp(ex, -0.65, 0.65) + kdX * (refVx - v.x) + 1.2 * intX;
      const azDes = kpZ * clamp(ez, -0.65, 0.65) + kdZ * (refVz - v.z) + 1.8 * intZ;
      const ayDes = kpY * clamp(ey, -0.60, 0.60) + kdY * (refVy - v.y) + 1.8 * intY;

      // Subtract wind + drag + disturbance so thrust acceleration produces axDes, ayDes, azDes
      const axThrust = clamp(axDes - cd * (wLead.x - v.x) - dAccX, -4.8, 4.8);
      const azThrust = clamp(azDes - cd * (wLead.z - v.z) - dAccZ, -4.8, 4.8);
      const ayThrust = clamp(G + ayDes + cd * v.y - dAccY, 3.5, 16.0);

      // Convert desired thrust acceleration vector (axThrust, ayThrust, azThrust) into roll, pitch, thrust
      // Rotate horizontal thrust vector into yaw-aligned frame:
      const fBodyX = cy * axThrust - sy * azThrust;
      const fBodyZ = -(sy * axThrust + cy * azThrust);
      const totalAcc = Math.hypot(axThrust, ayThrust, azThrust);

      const desRoll = clamp(Math.asin(clamp(-fBodyZ / totalAcc, -0.52, 0.52)), -0.52, 0.52);
      const cosRoll = Math.max(0.7, Math.cos(desRoll));
      const desPitch = clamp(Math.atan2(fBodyX, ayThrust), -0.52, 0.52);

      // Outer attitude trim integral to cancel weak-motor torque offset
      if (p.y > BODY_H + 0.02) {
        trimRoll = clamp(trimRoll + (desRoll - att.roll) * 2.2 * dt, -0.42, 0.42);
        trimPitch = clamp(trimPitch + (desPitch - att.pitch) * 2.2 * dt, -0.42, 0.42);
      }

      const cmdRoll = clamp(desRoll + 0.35 * (desRoll - att.roll) - 0.08 * rates.roll + trimRoll, -0.6, 0.6);
      const cmdPitch = clamp(desPitch + 0.35 * (desPitch - att.pitch) - 0.08 * rates.pitch + trimPitch, -0.6, 0.6);

      const actualCos = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp((ayThrust / actualCos) / thrustScale, 0, 1);
      const cmdYawRate = clamp(-1.0 * att.yaw - 0.25 * rates.yaw, -0.8, 0.8);

      const action = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      lastAction = action;
      return action;
    },
  };
}

