      else intY *= 0.95;

      const vDesX = clamp(kpPosX * ex + vffX, -vMaxX, vMaxX);
      const vDesZ = clamp(kpPosZ * ez + vffZ, -vMaxZ, vMaxZ);
      const vDesY = clamp(kpPosY * ey + vffY, -vMaxY, vMaxY);

      const axDes = kvX * (vDesX - v.x) + 1.2 * intX;
      const azDes = kvZ * (vDesZ - v.z) + 1.6 * intZ;
      const ayDes = kvY * (vDesY - v.y) + 1.6 * intY;

      const leadTime = 0.07 + 1.2 * lagEst;
      const wLead = getLookaheadWind(t, leadTime);

      const axThrust = clamp(axDes - cd * (wLead.x - v.x) - dAccX, -5.0, 5.0);
      const azThrust = clamp(azDes - cd * (wLead.z - v.z) - dAccZ, -5.0, 5.0);
      const ayThrust = clamp(G + ayDes + cd * v.y - dAccY, 3.0, 16.0);

      const fBodyX = cy * axThrust - sy * azThrust;
      const fBodyZ = sy * axThrust + cy * azThrust;

      const desPitch = clamp(Math.atan2(fBodyX, ayThrust), -0.52, 0.52);
      const desRoll = clamp(Math.atan2(-fBodyZ, Math.hypot(fBodyX, ayThrust)), -0.52, 0.52);

      const cmdRoll = clamp(desRoll - 0.05 * rates.roll + trimRoll, -0.6, 0.6);
      const cmdPitch = clamp(desPitch - 0.05 * rates.pitch + trimPitch, -0.6, 0.6);

      const actualCos = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp((ayThrust / actualCos) / thrustScale, 0, 1);
      const cmdYawRate = clamp(-1.0 * att.yaw - 0.25 * rates.yaw, -0.8, 0.8);

      const action = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      lastAction = action;
      return action;
    },
  };
}

