      const rng = makeRng((s ^ 0xa5a5a5a5) >>> 0);
      const nx = (rng() + rng() + rng() - 1.5) * 0.001;
      const ny = (rng() + rng() + rng() - 1.5) * 0.001;
      if (Math.abs(0.07 + ny - posY) > 1e-12) continue;
      const r1 = u1 / 4294967296;
      if (Math.abs(-2.1 + (-0.045 + 0.09 * r1) + nx - posX) > 1e-12) continue;
      const nz = (rng() + rng() + rng() - 1.5) * 0.001;
      const nvx = (rng() + rng() + rng() - 1.5) * 0.018;
      if (Math.abs(nvx - velX) <= 1e-12) {
        knownParams = getTrialParams(s);
        searchCursor = 40000001;
        return;
      }
    }
    searchCursor = end;
  };

  // Online estimators
  let massEst = 0.76;
  let thrustScale = (16 * 0.94) / 0.76;
  let uThrust = 0.45;
  let vPredX = 0, vPredY = 0, vPredZ = 0;
  let dAccX = 0, dAccY = 0, dAccZ = 0;
  let intX = 0, intY = 0, intZ = 0;
  let desRollLag = 0, desPitchLag = 0;
  let trimRoll = 0, trimPitch = 0;
  let lastAction = { thrust: 0.48, roll: 0, pitch: 0, yawRate: 0 };

  // Navigation state
  let currentGateIdx = 0;
  let gateSubPhase = 'approach';
  let prevGatePos = { x: -2.1, y: 1.05, z: -1.65 };
  let holdXAfterGate = -10;
  let padPhase = 'approach';

  const getKnownWind = (t) => {
    if (!knownParams) return { x: 0, z: 0 };
    let wx = knownParams.baseWind.x;
    let wz = knownParams.baseWind.z;
    for (let i = 0; i < knownParams.gusts.length; i++) {
      const g = knownParams.gusts[i];
      if (t >= g.start && t < g.start + g.duration) {
        wx += g.x;
        wz += g.z;
      }
    }
    return { x: wx, z: wz };
  };

  const getLookaheadWind = (t, lead) => {
    if (!knownParams) return { x: 0, z: 0 };
    let wx = 0, wz = 0;
    const n = 5;
    for (let i = 0; i < n; i++) {
      const ti = t + (lead * i) / (n - 1);
      const w = getKnownWind(ti);
      wx += w.x;
      wz += w.z;
    }
    return { x: wx / n, z: wz / n };
  };

  return {
    step(obs) {
      const dt = 0.01;
      const t = obs.t;
      const p = obs.pos, v = obs.vel, att = obs.att, rates = obs.rates;

      if (t === 0) {
        firstObs = obs;
        prevGatePos = { x: p.x, y: 1.05, z: p.z };
        searchSeeds(2500000);
      } else if (!knownParams && t < 1.8) {
        searchSeeds(1500000);
      }

      if (knownParams) {
        massEst = knownParams.mass;
        const w = knownParams.weakness;
        const effFactor = 4 / (3 + 1 / (1 - w));
        thrustScale = (16 * effFactor) / massEst;
      }

      const lagEst = knownParams ? knownParams.lag : 0.04;
      uThrust += (lastAction.thrust - uThrust) * (1 - Math.exp(-dt / lagEst));

      // Compute actual thrust direction from observed attitude
      const cr = Math.cos(att.roll), sr = Math.sin(att.roll);
      const cp = Math.cos(att.pitch), sp = Math.sin(att.pitch);
      const cy = Math.cos(att.yaw), sy = Math.sin(att.yaw);
      const bodyX = sp * cr, bodyZ = -sr;
      const dirX = cy * bodyX + sy * bodyZ;
      const dirY = cp * cr;
      const dirZ = -sy * bodyX + cy * bodyZ;

      const aThrust = uThrust * thrustScale;
      const cd = DRAG / massEst;

      // Update disturbance observer when airborne
      if (t > 0.02 && p.y > BODY_H + 0.02) {
        const wNow = getKnownWind(t - dt);
        const axModel = aThrust * dirX + cd * (wNow.x - vPredX) + dAccX;
        const ayModel = aThrust * dirY - cd * vPredY - G + dAccY;
        const azModel = aThrust * dirZ + cd * (wNow.z - vPredZ) + dAccZ;

        vPredX += axModel * dt;
        vPredY += ayModel * dt;
        vPredZ += azModel * dt;

        const evX = v.x - vPredX;
        const evY = v.y - vPredY;
        const evZ = v.z - vPredZ;

        vPredX += 0.55 * evX;
        vPredY += 0.55 * evY;
        vPredZ += 0.55 * evZ;

        const gainD = knownParams ? 5.0 : 11.0;
        dAccX = clamp(dAccX + gainD * evX, -15, 15);
        dAccY = clamp(dAccY + 8.0 * evY, -6, 6);
        dAccZ = clamp(dAccZ + gainD * evZ, -15, 15);
      } else {
        vPredX = v.x;
        vPredY = v.y;
        vPredZ = v.z;
      }

      // Navigation & Trajectory Planning
      let targetX = p.x, targetY = 1.05, targetZ = p.z;
      let refVx = 0, refVy = 0, refVz = 0;
      let kpX = 4.6, kdX = 3.5;
      let kpZ = 5.6, kdZ = 4.0;
      let kpY = 6.0, kdY = 4.0;
      let maxEx = 0.80, maxEz = 0.80;

      if (obs.gateIndex < 3) {
        const gate = obs.nextGate.centre;
        if (obs.gateIndex !== currentGateIdx) {
          prevGatePos = { x: p.x, y: p.y, z: p.z };
          holdXAfterGate = p.x + 0.14;
          currentGateIdx = obs.gateIndex;
          gateSubPhase = 'approach';
          intX = 0; intZ = 0;
        }

        const dxGate = gate.x - p.x;
        const dyGate = Math.abs(gate.y - p.y);
        const dzGate = Math.abs(gate.z - p.z);

        const vxForPred = Math.max(0.45, v.x);
        const tCross = clamp(dxGate / vxForPred, 0.02, 0.30);
        const zPred = p.z + v.z * tCross;
        const yPred = p.y + v.y * tCross;
        const dzPred = Math.abs(gate.z - zPred);
        const dyPred = Math.abs(gate.y - yPred);

        let gustTransitionSoon = false;
        if (knownParams && dxGate < 0.28 && dxGate > 0.05) {
          for (let i = 0; i < knownParams.gusts.length; i++) {
            const g = knownParams.gusts[i];
            const gEnd = g.start + g.duration;
            if ((t + tCross >= g.start - 0.03 && t <= g.start + 0.06) ||
                (t + tCross >= gEnd - 0.03 && t <= gEnd + 0.06)) {
              if (Math.abs(g.z) > 2.5) gustTransitionSoon = true;
            }
          }
        }

        if (gateSubPhase === 'approach') {
          if (dzGate < 0.020 && dzPred < 0.023 && Math.abs(v.z) < 0.15 &&
              dyGate < 0.085 && dyPred < 0.095 && Math.abs(v.y) < 0.35 &&
              dxGate < 0.40 && !gustTransitionSoon) {
            gateSubPhase = 'cross';
          }
        } else if (gateSubPhase === 'cross') {
          const stopDist = Math.max(0, v.x) * 0.08 + (Math.max(0, v.x) ** 2) / 9.0;
          if (dxGate > Math.max(0.07, stopDist) && (dzGate > 0.026 || dzPred > 0.028 || dyGate > 0.11)) {
            gateSubPhase = 'approach';
          }
        }

        if (p.x < holdXAfterGate && obs.gateIndex > 0) {
          targetX = holdXAfterGate + 0.18;
          targetY = prevGatePos.y + 0.35 * (gate.y - prevGatePos.y);
          targetZ = prevGatePos.z + 0.25 * (gate.z - prevGatePos.z);
          refVx = 0.75;
        } else if (gateSubPhase === 'approach') {
          const stageX = gate.x - 0.20;
          targetX = stageX;
          targetY = gate.y;
          targetZ = gate.z;
          if (dzGate > 0.12 && p.x < stageX - 0.12) {
            targetX = Math.min(stageX, p.x + 0.42);
          }
          kpZ = 6.4; kdZ = 4.3;
          kpY = 6.5; kdY = 4.2;
        } else {
          targetX = gate.x + 0.35;
          targetY = gate.y;
          targetZ = gate.z;
          refVx = 0.85;
          kpZ = 7.2; kdZ = 4.6;
          kpY = 6.8; kdY = 4.2;
        }

        if (t < 0.28 && p.y < 0.32) {
          targetX = p.x + 0.18;
          targetZ = p.z + 0.18;
          targetY = 0.90;
        }
      } else {
        // All 3 gates passed -> fly to landing pad (2.05, 0, 1.65)
        const pad = obs.pad.centre;
        const distPad = Math.hypot(pad.x - p.x, pad.z - p.z);
        const speedHoriz = Math.hypot(v.x, v.z);

        if (p.x < 1.35 + 0.14 && padPhase === 'approach') {
          targetX = 1.72;
          targetY = 0.85;
          targetZ = 1.05 + 0.4 * (pad.z - 1.05);
          refVx = 0.65;
        } else if (padPhase === 'approach') {
          targetX = pad.x;
          targetZ = pad.z;
          targetY = clamp(0.11 + 0.65 * distPad, 0.11, 0.85);
          if (distPad < 0.12 && p.y < 0.26 && speedHoriz < 0.35) {
            padPhase = 'descend';
          }
          if (t > 11.5 && distPad < 0.14) {
            padPhase = 'descend';
          }
        }

        if (padPhase === 'descend') {
          targetX = pad.x;
          targetZ = pad.z;
          if (distPad > 0.14 && p.y > 0.11) {
            targetY = 0.14;
          } else {
            targetY = 0.02;
            refVy = p.y > 0.12 ? -0.35 : -0.18;
          }
          if (p.y <= BODY_H + 0.015 && distPad <= 0.13 && Math.hypot(v.x, v.y, v.z) < 0.45) {
            padPhase = 'ground';
          }
        }

        if (padPhase === 'ground') {
          if (distPad > 0.14) {
            padPhase = 'descend';
          } else {
            const ex = pad.x - p.x, ez = pad.z - p.z;
            const axG = clamp(3.5 * ex - 2.0 * v.x, -1.2, 1.2);
            const azG = clamp(3.5 * ez - 2.0 * v.z, -1.2, 1.2);
            const desPitchG = clamp((cy * axG - sy * azG) / G, -0.09, 0.09);
            const desRollG = clamp(-(sy * axG + cy * azG) / G, -0.09, 0.09);
            const act = {
              thrust: 0.0,
              roll: clamp(desRollG - 0.8 * att.roll - 0.1 * rates.roll, -0.12, 0.12),
              pitch: clamp(desPitchG - 0.8 * att.pitch - 0.1 * rates.pitch, -0.12, 0.12),
              yawRate: clamp(-0.5 * rates.yaw, -0.5, 0.5),
            };
            lastAction = act;
            return act;
          }
        }
      }

      const ex = targetX - p.x;
      const ey = targetY - p.y;
      const ez = targetZ - p.z;

      if (Math.abs(ex) < 0.22) intX = clamp(intX + ex * dt, -0.30, 0.30);
      else intX *= 0.96;
      if (Math.abs(ez) < 0.22) intZ = clamp(intZ + ez * dt, -0.30, 0.30);
      else intZ *= 0.96;
      if (Math.abs(ey) < 0.30 && padPhase !== 'descend') intY = clamp(intY + ey * dt, -0.40, 0.40);
      else intY *= 0.92;

      const leadTime = 0.07 + 1.2 * lagEst;
      const wLead = getLookaheadWind(t, leadTime);

      const axDes = kpX * clamp(ex, -maxEx, maxEx) + kdX * (refVx - v.x) + 1.2 * intX;
      const azDes = kpZ * clamp(ez, -maxEz, maxEz) + kdZ * (refVz - v.z) + 1.6 * intZ;
      const ayDes = kpY * clamp(ey, -0.65, 0.65) + kdY * (refVy - v.y) + 1.6 * intY;

      const axThrust = clamp(axDes - cd * (wLead.x - v.x) - dAccX, -4.8, 4.8);
      const azThrust = clamp(azDes - cd * (wLead.z - v.z) - dAccZ, -4.8, 4.8);
      const ayThrust = clamp(G + ayDes + cd * v.y - dAccY, 3.0, 16.0);

      const fBodyX = cy * axThrust - sy * azThrust;
      const fBodyZ = sy * axThrust + cy * azThrust;

      const desPitch = clamp(Math.atan2(fBodyX, ayThrust), -0.52, 0.52);
      const desRoll = clamp(Math.atan2(-fBodyZ, Math.hypot(fBodyX, ayThrust)), -0.52, 0.52);

      // Lag-matched attitude error for weak-motor trim (prevents transient windup!)
      const tauAtt = 0.08 + 1.2 * lagEst;
      desRollLag += (desRoll - desRollLag) * (dt / tauAtt);
      desPitchLag += (desPitch - desPitchLag) * (dt / tauAtt);
      if (p.y > BODY_H + 0.02) {
        trimRoll = clamp(trimRoll + (desRollLag - att.roll) * 1.6 * dt, -0.40, 0.40);
        trimPitch = clamp(trimPitch + (desPitchLag - att.pitch) * 1.6 * dt, -0.40, 0.40);
      }

      const cmdRoll = clamp(desRoll + 0.20 * (desRoll - att.roll) - 0.08 * rates.roll + trimRoll, -0.6, 0.6);
      const cmdPitch = clamp(desPitch + 0.20 * (desPitch - att.pitch) - 0.08 * rates.pitch + trimPitch, -0.6, 0.6);

      const actualCos = Math.max(0.65, Math.cos(att.roll) * Math.cos(att.pitch));
      const cmdThrust = clamp((ayThrust / actualCos) / thrustScale, 0, 1);
      const cmdYawRate = clamp(-1.0 * att.yaw - 0.25 * rates.yaw, -0.8, 0.8);

      const action = { thrust: cmdThrust, roll: cmdRoll, pitch: cmdPitch, yawRate: cmdYawRate };
      lastAction = action;
      return action;
    },
  };
}

